package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import com.lianxibu.site.controller.jobs.OwnerAdHocQuestionController;
import com.lianxibu.site.config.OwnerAdHocQuestionRuntimeConfiguration;
import com.lianxibu.site.service.identity.IdentityService;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.boot.test.context.runner.ApplicationContextRunner;
import org.springframework.test.web.servlet.*;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;

/** Real HTTP projection of the actual original native read provider. */
class OwnerAdHocQuestionHttpTest {
 OwnerAdHocQuestionReadTest f;IdentityService identity;
 OwnerAdHocQuestionReadTest fixture(){return new OwnerAdHocQuestionReadTest();}
 @BeforeEach void setup(){f=fixture();f.setup();identity=mock(IdentityService.class);when(identity.authenticate("fictional-session")).thenReturn(f.c.owner);when(identity.authenticate("fictional-member")).thenReturn(new IdentityService.Actor("fictional-member","member"));}
 @AfterEach void close(){f.restoreFixtureTimezone();}
 ApplicationContextRunner context(){return new ApplicationContextRunner().withUserConfiguration(OwnerAdHocQuestionRuntimeConfiguration.class).withBean(javax.sql.DataSource.class,()->f.c.f.source).withBean(org.springframework.transaction.PlatformTransactionManager.class,()->f.tx).withPropertyValues("site.browser.enabled=true","site.content.enabled=true","site.execution.enabled=true","site.execution.ad-hoc.enabled=false");}
 @SuppressWarnings("unchecked") MockMvc mvc(ObjectProvider<OwnerAdHocQuestionReadService> reads){ObjectProvider<IdentityService> auth=mock(ObjectProvider.class);when(auth.getIfAvailable()).thenReturn(identity);return MockMvcBuilders.standaloneSetup(new OwnerAdHocQuestionController(auth,reads)).build();}
 org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder request(String id){return get("/admin/jobs/{id}/ad-hoc",id).cookie(new jakarta.servlet.http.Cookie("lianxibu_session","fictional-session"));}
 @Test void ActualSpringBeanAndHttpKeepOriginalQuestionLinkAndNativeRetainedAnswer(){context().run(c->{assertNull(c.getStartupFailure());assertEquals(1,c.getBeansOfType(OwnerAdHocQuestionReadService.class).size());var api=mvc(c.getBeanProvider(OwnerAdHocQuestionReadService.class));String id=f.accepted.command().intentId();api.perform(request(id)).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store")).andExpect(jsonPath("$.data.intent.id").value(id)).andExpect(jsonPath("$.data.original_request.prompt").value(f.accepted.command().prompt())).andExpect(jsonPath("$.data.prepared_job").isEmpty()).andExpect(jsonPath("$.data.retained_result").isEmpty());f.prepare();api.perform(request(id)).andExpect(status().isOk()).andExpect(jsonPath("$.data.prepared_job.id").value(f.accepted.command().rootId())).andExpect(jsonPath("$.data.prepared_job.call_count").value(0));f.answer();var result=api.perform(request(id)).andExpect(status().isOk()).andExpect(jsonPath("$.data.retained_result.payload.kind").value("ad_hoc")).andExpect(jsonPath("$.data.retained_result.payload.title").value("Fictional retained answer")).andExpect(jsonPath("$.data.prepared_job.call_count").value(1)).andReturn().getResponse().getContentAsString();assertFalse(result.contains("Fictional original reason"));assertFalse(result.contains("fictional-focus"));assertEquals(1,f.sends);});}
 @Test void AuthenticationAndRoleComeBeforeQueryParsingAndBrokenStorage(){context().run(c->{var api=mvc(c.getBeanProvider(OwnerAdHocQuestionReadService.class));f.c.f.jdbc.execute("DROP TABLE jobs");api.perform(get("/admin/jobs/fictional-id/ad-hoc").queryParam("unexpected","fictional")).andExpect(status().isUnauthorized());api.perform(get("/admin/jobs/fictional-id/ad-hoc").queryParam("unexpected","fictional").cookie(new jakarta.servlet.http.Cookie("lianxibu_session","fictional-member"))).andExpect(status().isForbidden());api.perform(request(f.accepted.command().intentId())).andExpect(status().isServiceUnavailable()).andExpect(header().string("Retry-After","1"));});}
 @Test void UnknownOrDuplicateQueriesMissingAndWrongRecordIdentitiesAreExplicit(){context().run(c->{var api=mvc(c.getBeanProvider(OwnerAdHocQuestionReadService.class));String id=f.accepted.command().intentId();api.perform(request(id).queryParam("unexpected","fictional")).andExpect(status().isBadRequest());api.perform(request(id).queryParam("id","fictional-a","fictional-b")).andExpect(status().isBadRequest());api.perform(request("fictional-absent")).andExpect(status().isNotFound());f.prepare();api.perform(request(f.accepted.command().rootId())).andExpect(status().isNotFound());});}
 @Test void DamagedPreparedOrRetainedProofProducesSanitized503RatherThanEmptyAnswer(){context().run(c->{var api=mvc(c.getBeanProvider(OwnerAdHocQuestionReadService.class));f.answer();f.c.f.jdbc.update("UPDATE jobs SET payload_hash=? WHERE purpose='result'",new byte[32]);var body=api.perform(request(f.accepted.command().intentId())).andExpect(status().isServiceUnavailable()).andExpect(header().string("Cache-Control","no-store")).andExpect(header().string("Retry-After","1")).andExpect(jsonPath("$.error.code").value("temporarily_unavailable")).andReturn().getResponse().getContentAsString();assertFalse(body.contains(f.accepted.command().prompt()));assertFalse(body.contains("SELECT"));assertEquals(1,f.sends);});}
 @Test void DisabledOrIncompleteThreeFlagsHaveNoBeanOrDatabaseWork(){var source=mock(javax.sql.DataSource.class);var tx=mock(org.springframework.transaction.PlatformTransactionManager.class);for(String flags:new String[]{"","site.browser.enabled=true","site.browser.enabled=true,site.content.enabled=true","site.browser.enabled=true,site.content.enabled=true,site.execution.enabled=false"}){new ApplicationContextRunner().withUserConfiguration(OwnerAdHocQuestionRuntimeConfiguration.class).withBean(javax.sql.DataSource.class,()->source).withBean(org.springframework.transaction.PlatformTransactionManager.class,()->tx).withPropertyValues(flags.isEmpty()?new String[0]:flags.split(",")).run(c->{assertNull(c.getStartupFailure());assertTrue(c.getBeansOfType(OwnerAdHocQuestionReadService.class).isEmpty());var api=mvc(c.getBeanProvider(OwnerAdHocQuestionReadService.class));api.perform(request(f.accepted.command().intentId())).andExpect(status().isServiceUnavailable());});}verifyNoInteractions(source,tx);}
}
